export function m34ThemeSelectionPrevious(raw, file) {
  const selected = m34ThemeSelectionSourceHistory.find(row => row.path === file);
  if (!selected) return raw;
  const identity = body => ({
    path: file,
    bytes: body.length,
    sha256: createHash('sha256').update(body).digest('hex')
  });
  if (JSON.stringify(identity(raw)) !== JSON.stringify(selected.current)) return raw;
  let text = raw.toString('utf8');
  for (const inverse of selected.inverse) {
    if (text.split(inverse.from).length !== 2) throw Error('Exact M3.4 theme selection inverse differs');
    text = text.replace(inverse.from, () => inverse.to);
  }
  const previous = Buffer.from(text);
  if (JSON.stringify(identity(previous)) !== JSON.stringify(selected.predecessor))
    throw Error('Complete M3.4 theme selection predecessor differs');
  return previous;
}

