export function worldCardBoundaryPrevious(raw, file) {
  raw = world3dBoundaryPrevious(raw, file);
  const identity = body => ({
    path: file,
    bytes: body.length,
    sha256: createHash('sha256').update(body).digest('hex')
  });
  for (const [history, marker] of [
    [importedGlbAnimationBoundaryHistory, 'IMPORTED-GLB-ANIMATION'],
    [sceneAnimationBoundaryHistory, 'SCENE-ANIMATION'],
    [lambertGlbBoundaryHistory, 'LAMBERT-GLB'],
    [texturedGlbBoundaryHistory, 'TEXTURED-GLB'],
    [worldCardBoundaryHistory, 'WORLD-CARD']
  ]) {
    const selected = history.find(row => row.path === file);
    if (!selected || JSON.stringify(identity(raw)) !== JSON.stringify(selected.current)) continue;
    let text = raw.toString('utf8');
    const prefix = selected.insertion ? '// ' + marker + '-RAW-' : '  // ' + marker + '-GRAPH-';
    const start = prefix + 'BEGIN\n',
      end = prefix + 'END\n';
    assert.equal(text.split(start).length, 2);
    assert.equal(text.split(end).length, 2);
    const first = text.indexOf(start),
      last = text.indexOf(end, first + start.length);
    assert.ok(last > first);
    text = text.slice(0, first) + text.slice(last + end.length);
    if (selected.insertion) {
      assert.equal(text.split(selected.insertion).length, 2);
      text = text.replace(selected.insertion, '');
    }
    raw = Buffer.from(text);
    assert.deepEqual(identity(raw), selected.predecessor);
  }
  return raw;
}
export function authoredScenePrevious(raw, file) {
  raw = worldCardBoundaryPrevious(raw, file);
  const selected = authoredSceneSourceHistory.find(row => row.path === file);
  if (!selected) return raw;
  const identity = body => ({
    path: file,
    bytes: body.length,
    sha256: createHash('sha256').update(body).digest('hex')
  });
  if (JSON.stringify(identity(raw)) !== JSON.stringify(selected.current)) return raw;
  let text = raw.toString('utf8');
  for (const [start, end] of [
    ['// AUTHORED-SCENE-PACKAGE-BEGIN\n', '// AUTHORED-SCENE-PACKAGE-END\n'],
    ['  // AUTHORED-SCENE-GRAPH-BEGIN\n', '  // AUTHORED-SCENE-GRAPH-END\n']
  ]) {
    const first = text.indexOf(start);
    if (first < 0) continue;
    const last = text.indexOf(end, first + start.length);
    assert.equal(text.split(start).length, 2);
    assert.equal(text.split(end).length, 2);
    assert.ok(last > first);
    text = text.slice(0, first) + text.slice(last + end.length);
  }
  text = text.replace(
    " if(expected?.path==='packages/engine/package.json')raw=projectAuthoredScenePackage(raw);\n",
    ''
  );
  text = text.replace(
    '    if(name===\'engine\'&&equal(value.exports?.[\'./scene3d/authoring\'],{"types":"./dist/rendering/scene3dAuthoring.d.ts","import":"./dist/rendering/scene3dAuthoring.js"}))delete value.exports[\'./scene3d/authoring\'];\n',
    ''
  );
  const previous = Buffer.from(text);
  assert.deepEqual(identity(previous), selected.predecessor);
  return previous;
}
