export function importedGlbAnimationCompilerFixturePrevious(raw, file) {
  raw = world3dCompilerFixturePrevious(raw, file);
  const selected = importedGlbAnimationCompilerHistory.find(row => row.path === file);
  if (!selected) return raw;
  const identity = body => ({
    path: file,
    bytes: body.length,
    sha256: createHash('sha256').update(body).digest('hex')
  });
  if (JSON.stringify(identity(raw)) !== JSON.stringify(selected.current)) return raw;
  let text = raw.toString('utf8');
  for (const step of selected.inverse ?? [{ from: importedGlbAnimationCompilerSuffix, to: '' }]) {
    assert.equal(text.split(step.from).length, 2);
    text = text.replace(step.from, () => step.to);
  }
  const previous = Buffer.from(text);
  assert.deepEqual(identity(previous), selected.predecessor);
  return previous;
}
