export function m24ResetPrevious(raw, file) {
  raw = authoredSceneCompilerFixturePrevious(raw, file);
  raw = uiControlsPrevious(raw, file);
  const selected = m24ResetSourceHistory.find(row => row.path === file);
  if (!selected) return raw;
  const identity = body => ({
    path: file,
    bytes: body.length,
    sha256: createHash('sha256').update(body).digest('hex')
  });
  if (JSON.stringify(identity(raw)) !== JSON.stringify(selected.current)) return raw;
  let text = raw.toString('utf8');
  for (const inverse of selected.inverse) {
    if (text.split(inverse.from).length !== 2) throw Error('Exact RESET source inverse differs');
    text = text.replace(inverse.from, () => inverse.to);
  }
  const previous = Buffer.from(text);
  if (JSON.stringify(identity(previous)) !== JSON.stringify(selected.predecessor))
    throw Error('Complete RESET predecessor differs');
  return previous;
}

