export function geometryStrictPrevious(raw, file) {
  const selected = geometryStrictSourceHistory.find(row => row.path === file);
  if (!selected) return raw;
  const identity = body => ({
    path: file,
    bytes: body.length,
    sha256: createHash('sha256').update(body).digest('hex')
  });
  if (JSON.stringify(identity(raw)) !== JSON.stringify(selected.current)) return raw;
  const text = raw.toString('utf8');
  assert.equal(text.split(geometryStrictBootstrap.after).length, 2);
  const previous = Buffer.from(text.replace(geometryStrictBootstrap.after, geometryStrictBootstrap.before));
  assert.deepEqual(identity(previous), selected.predecessor);
  return previous;
}

