export function worldCardHostPrevious(raw, file) {
  const identity = body => ({
    path: file,
    bytes: body.length,
    sha256: createHash('sha256').update(body).digest('hex')
  });
  for (const { current, predecessor, inverse } of [
    lambertGlbHostHistory,
    texturedGlbHostHistory,
    worldCardHostHistory
  ]) {
    if (file !== current.path || JSON.stringify(identity(raw)) !== JSON.stringify(current)) continue;
    let text = raw.toString('utf8');
    for (const { from, to } of inverse) {
      assert.equal(text.split(from).length, 2);
      text = text.replace(from, () => to);
    }
    raw = Buffer.from(text);
    assert.deepEqual(identity(raw), predecessor);
  }
  return raw;
}
