export function removedLegacyCapturePrevious(raw, file) {
  const selected = removedLegacyCaptureHistory.find(row => row.path === file);
  if (!selected) return raw;
  const identity = body => ({
    path: file,
    bytes: body.length,
    sha256: createHash('sha256').update(body).digest('hex')
  });
  if (JSON.stringify(identity(raw)) !== JSON.stringify(selected.current)) return raw;
  let text = raw.toString('utf8');
  for (const inverse of selected.inverse) {
    if (text.split(inverse.from).length !== 2) throw Error('Exact legacy capture inverse differs');
    text = text.replace(inverse.from, () => inverse.to);
  }
  const previous = Buffer.from(text);
  if (JSON.stringify(identity(previous)) !== JSON.stringify(selected.predecessor))
    throw Error('Complete legacy capture predecessor differs');
  return previous;
}
// REMOVED-LEGACY-CAPTURE-HISTORY-END

export function m24SpinePrevious(raw, file) {
  raw = m12FullDirtyCapturePrevious(removedLegacyCapturePrevious(raw, file), file);
  raw = worldCardHostPrevious(m34ThemePrevious(raw, file), file);
  const selected = m24SpineSourceHistory.find(row => row.path === file);
  if (!selected) return raw;
  const identity = body => ({
    path: file,
    bytes: body.length,
    sha256: createHash('sha256').update(body).digest('hex')
  });
  if (JSON.stringify(identity(raw)) !== JSON.stringify(selected.current)) return raw;
  let text = raw.toString('utf8');
  for (const inverse of selected.inverse) {
    if (text.split(inverse.from).length !== 2) throw Error('Exact M2.4 source inverse differs');
    text = text.replace(inverse.from, () => inverse.to);
  }
  const previous = Buffer.from(text);
  if (JSON.stringify(identity(previous)) !== JSON.stringify(selected.predecessor))
    throw Error('Complete M2.4 predecessor differs');
  return previous;
}
// M24-SPINE-SOURCE-HISTORY-END

export function m3KeyRevealPrevious(raw, file) {
  raw = m24SpinePrevious(raw, file);
  const selected = m3KeyRevealSourceHistory.find(row => row.path === file);
  if (!selected) return raw;
  const identity = body => ({
    path: file,
    bytes: body.length,
    sha256: createHash('sha256').update(body).digest('hex')
  });
  if (JSON.stringify(identity(raw)) !== JSON.stringify(selected.current)) return raw;
  let text = raw.toString('utf8');
  if (text.split(selected.block).length !== 2) throw Error('Exact key-reveal source block differs');
  text = text.replace(selected.block, '');
  for (const inverse of selected.inverse) {
    if (text.split(inverse.from).length !== 2) throw Error('Exact key-reveal source inverse differs');
    text = text.replace(inverse.from, inverse.to);
  }
  const previous = Buffer.from(text);
  if (JSON.stringify(identity(previous)) !== JSON.stringify(selected.predecessor))
    throw Error('Complete key-reveal predecessor differs');
  return previous;
}

export function m33KeyboardPrevious(raw, selected) {
  raw = m3KeyRevealPrevious(raw, selected?.path);
  if (!selected) return raw;
  const identity = body => ({
    path: selected.path,
    bytes: body.length,
    sha256: createHash('sha256').update(body).digest('hex')
  });
  if (JSON.stringify(identity(raw)) !== JSON.stringify(selected.current)) return raw;
  let text = raw.toString('utf8');
  for (const inverse of selected.inverse) {
    if (text.split(inverse.from).length !== 2) throw Error('M3.3 exact keyboard source inverse differs');
    text = text.replace(inverse.from, inverse.to);
  }
  const previous = Buffer.from(text);
  if (JSON.stringify(identity(previous)) !== JSON.stringify(selected.predecessor))
    throw Error('M3.3 complete keyboard source predecessor differs');
  return previous;
}

export function m22SequencePrevious(raw, selected) {
  raw = m33KeyboardPrevious(
    raw,
    m33KeyboardSourceHistory.find(row => row.path === selected?.path)
  );
  if (!selected) return raw;
  const identity = body => ({
    path: selected.path,
    bytes: body.length,
    sha256: createHash('sha256').update(body).digest('hex')
  });
  if (JSON.stringify(identity(raw)) !== JSON.stringify(selected.current)) return raw;
  let text = raw.toString('utf8');
  if (selected.block) {
    if (text.split(selected.block).length !== 2) throw Error('M2.2 exact source block differs');
    text = text.replace(selected.block, '');
  }
  for (const inverse of selected.inverse) {
    if (text.split(inverse.from).length !== 2) throw Error('M2.2 exact source inverse differs');
    text = text.replace(inverse.from, inverse.to);
  }
  const previous = Buffer.from(text);
  if (JSON.stringify(identity(previous)) !== JSON.stringify(selected.predecessor))
    throw Error('M2.2 complete source predecessor differs');
  return previous;
}

