export function m21ContentStrictPredecessor(file, raw) {
  const selected = m21ContentStrictHistory.find(row => row.path === file);
  if (!selected) return raw;
  const identity = body => ({ bytes: body.length, sha256: createHash('sha256').update(body).digest('hex') });
  if (JSON.stringify(identity(raw)) === JSON.stringify(selected.predecessor)) return raw;
  assert.deepEqual(identity(raw), selected.current);
  let text = raw.toString();
  assert.equal(text.split(m21ContentBootstrapAfter).length, 2);
  text = text.replace(m21ContentBootstrapAfter, m33BootstrapAfter);
  if (file === 'tools/sequence-playback-types.mjs') {
    const after = 'for (const pin of m13?.compilerPins ?? seqpInventory.compiler.pins) seqpReadPin(pin);',
      before = 'for (const pin of seqpInventory.compiler.pins) seqpReadPin(pin);';
    assert.equal(text.split(after).length, 3);
    text = text.replaceAll(after, before);
  }
  const previous = Buffer.from(text);
  assert.deepEqual(identity(previous), selected.predecessor);
  return previous;
}
